import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { select, editor, Separator } from "@inquirer/prompts";
import pc from "picocolors";
import { execCapture as defaultExecCapture, which as defaultWhich } from "../lib/env.js";
import { logger } from "../lib/logger.js";
import type {
  DecisionDeps,
  FileKind,
  PlanEntry,
  StrategyMode,
} from "./decision.js";

/**
 * Default `DecisionDeps` for production use.
 *
 * Wires the real @inquirer/prompts `select` (arrow-navigation) and `editor` prompts plus the
 * `diff` CLI (with a read-and-print fallback when `diff` is not installed)
 * into the dependency-injected decision layer. Tests bypass this module
 * entirely and construct fake `DecisionDeps` to drive every branch.
 *
 * `target` and `assetsRoot` are stashed on the returned object so the
 * `openEditor` adapter can resolve absolute paths for the file it streams
 * into the editor. They are intentionally NOT used by `promptStrategy` or
 * `promptFileDecision` — those only need to know the per-file entry.
 */
export function buildDefaultDecisionDeps(
  target: string,
  assetsRoot: string,
  overrides: BuildDefaultDecisionDepsOptions = {},
): DecisionDeps {
  const which = overrides.which ?? defaultWhich;
  const execCapture = overrides.execCapture ?? defaultExecCapture;
  return {
    promptStrategy: defaultPromptStrategy,
    promptFileDecision: defaultPromptFileDecision,
    renderUnifiedDiff: (relPath, kind) =>
      defaultRenderUnifiedDiffForEntry(relPath, kind, {
        target,
        assetsRoot,
        which,
        execCapture,
      }),
    openEditor: (relPath: string) => defaultOpenEditor(relPath, target, assetsRoot),
    sha256Content: defaultSha256Content,
  };
}

/** Optional overrides for `buildDefaultDecisionDeps`. All fields default
 * to the real implementation from `lib/env.js`. Tests use these to inject
 * stubs (e.g. simulate a missing `diff` binary). */
export interface BuildDefaultDecisionDepsOptions {
  which?: (cmd: string) => string | null;
  execCapture?: typeof defaultExecCapture;
}

/**
 * Top-level strategy picker: batch-adopt (default), batch-keep, or per-file.
 *
 * Uses the @inquirer/prompts `select` widget so the user navigates with
 * arrow keys instead of typing a single letter. `select` highlights the
 * default choice by matching `default` against a choice's `value`, so the
 * `default` string must be one of the `value`s below — not a letter key
 * or an index.
 */
async function defaultPromptStrategy(): Promise<StrategyMode> {
  const result = await select({
    message: "Choose upgrade strategy for interactive files",
    default: "all-adopt",
    choices: [
      {
        name: "Adopt new version for every file (recommended)",
        value: "all-adopt",
        description: "Overwrite all interactive files (0.1.1 behaviour)",
      },
      {
        name: "Keep my current files (skip all updates)",
        value: "all-keep",
        description: "Keep local changes, skip new content this run",
      },
      {
        name: "Decide per file",
        value: "per-file",
        description: "Review the diff and choose per file",
      },
    ],
  });
  if (result === "all-adopt" || result === "all-keep" || result === "per-file") return result;
  // Defensive: should never happen given the choices above.
  return "all-adopt";
}

/**
 * Per-file decision prompt. The choices vary by `kind` because the user's
 * mental model is different for an existing-but-modified file vs. a brand
 * new file vs. one slated for deletion under --prune.
 *
 * When `remaining > 0` we append two batch entries separated from the
 * base choices by a `Separator`:
 *
 *   - "Adopt all remaining (N)" — collapse every subsequent file to adopt.
 *   - "Keep all remaining (N)" — collapse every subsequent file to keep.
 *
 * The sentinel values `__adopt-all` / `__keep-all` are recognised by
 * `resolveUpgradeActions` to fan the decision out and exit the per-file loop.
 *
 * `select` highlights the default choice by matching `default` against a
 * choice's `value`; descriptions carry the contextual hint. We no longer
 * suffix `(default)` onto the choice name — the renderer renders the
 * highlight directly.
 */
type FileDecisionAnswer = "adopt" | "keep" | "edit" | "__adopt-all" | "__keep-all";

async function defaultPromptFileDecision(
  entry: PlanEntry,
  remaining: number,
  kind: FileKind,
): Promise<FileDecisionAnswer> {
  const header = describeEntry(entry);
  const defaultValue: FileDecisionAnswer = kind === "modified" ? "keep" : "adopt";
  const baseChoices: Array<{ name: string; value: FileDecisionAnswer; description?: string }> =
    kind === "modified"
      ? [
          {
            name: "Adopt new version",
            value: "adopt",
            description: "Overwrite local with the new version",
          },
          {
            name: "Keep my version",
            value: "keep",
            description: "Keep your local version (safe)",
          },
          {
            name: "Edit / merge manually in $EDITOR",
            value: "edit",
            description: "Merge the new version into local via $EDITOR",
          },
        ]
      : kind === "added"
        ? [
            {
              name: "Adopt new file",
              value: "adopt",
              description: "Write the new file",
            },
            {
              name: "Skip (don't add this file)",
              value: "keep",
              description: "Do not add this file",
            },
          ]
        : [
            {
              name: "Delete (--prune)",
              value: "adopt",
              description: "Delete this file (only effective with --prune)",
            },
            {
              name: "Keep my file",
              value: "keep",
              description: "Keep your local copy",
            },
          ];

  const batchChoices: Array<{ name: string; value: FileDecisionAnswer; description: string }> =
    remaining > 0
      ? [
          {
            name: `Adopt all remaining (${remaining})`,
            value: "__adopt-all",
            description: `Adopt the new version for all ${remaining} remaining files`,
          },
          {
            name: `Keep all remaining (${remaining})`,
            value: "__keep-all",
            description: `Keep local for all ${remaining} remaining files`,
          },
        ]
      : [];

  const answer = await select<FileDecisionAnswer>({
    message: header,
    default: defaultValue,
    choices:
      batchChoices.length > 0
        ? [...baseChoices, new Separator(), ...batchChoices]
        : baseChoices,
  });
  if (answer === "__adopt-all" || answer === "__keep-all") return answer;
  if (answer === "adopt" || answer === "keep" || answer === "edit") return answer;
  // Defensive: fall back to keep if the prompt somehow returns an unknown value.
  return "keep";
}

function describeEntry(entry: PlanEntry): string {
  const verb = entry.kind === "modified" ? "modified" : entry.kind === "added" ? "added" : "removed";
  return `${entry.relPath} (${verb})`;
}

/**
 * Render a unified diff for the file. Uses the system `diff` CLI when
 * available; otherwise prints the new version's full content under a clear
 * header so the user can still review what would land.
 *
 * Returns the rendered string (also printed to the upgrade log) so callers
 * that want to keep the diff around — e.g. for a `--diff-out` flag — can
 * consume it without re-running `diff`.
 *
 * This is the low-level helper that powers `defaultRenderUnifiedDiffForEntry`
 * (the kind-aware adapter wired into `DecisionDeps`). It is exported so
 * tests can exercise the `diff`/`readFileSync` fallback paths without
 * having to mock the whole `DecisionDeps` surface.
 */
async function defaultRenderUnifiedDiff(
  relPath: string,
  fromAbs: string,
  toAbs: string,
  deps: { which: (cmd: string) => string | null; execCapture: typeof defaultExecCapture } = {
    which: defaultWhich,
    execCapture: defaultExecCapture,
  },
): Promise<string> {
  logger.info(`--- unified diff for ${relPath} ---`);
  if (deps.which("diff") !== null) {
    const result = await deps.execCapture("diff", ["-u", fromAbs, toAbs]);
    const stdout = result.stdout.trim();
    if (stdout.length === 0) {
      logger.info("(files are identical)");
      return "";
    }
    for (const line of stdout.split(/\r?\n/)) printDiffLine(line);
    if (result.exitCode > 1) {
      // diff exits 1 when files differ — expected. > 1 means actual error.
      logger.warn(`diff exited ${result.exitCode}: ${result.stderr.trim()}`);
    }
    return stdout;
  }
  // Fallback: print the new version in full so the user can still review.
  logger.info("(diff CLI not found; showing new version in full)");
  logger.info("New version from assets:");
  const newContent = readFileSync(toAbs, "utf-8");
  for (const line of newContent.split(/\r?\n/)) printDiffLine(line);
  return newContent;
}

/**
 * Print a single line from a unified diff with git-style coloring.
 *
 * `diff -u` lines start with `+++ `/`--- ` (file headers), `@@` (hunk
 * header), `+` (added), `-` (removed), or a single space / nothing
 * (context). We dispatch by prefix — the file-header checks must run
 * first so `+++ b` does not also match the `+` rule. Output goes
 * straight to stdout via `console.log` so we do not double-wrap lines
 * in `logger.info`'s cyan (which would mutate git's color scheme).
 *
 * Non-diff lines (e.g. the readFileSync fallback body) have no
 * recognised prefix and pass through uncoloured.
 */
function printDiffLine(line: string): void {
  if (line.startsWith("+++ ") || line.startsWith("--- ")) {
    console.log(pc.dim(line));
  } else if (line.startsWith("@@")) {
    console.log(pc.cyan(line));
  } else if (line.startsWith("+")) {
    console.log(pc.green(line));
  } else if (line.startsWith("-")) {
    console.log(pc.red(line));
  } else {
    console.log(line);
  }
}

export { defaultRenderUnifiedDiff };

/**
 * Kind-aware adapter for the per-file diff preview that the decision
 * layer fires BEFORE `promptFileDecision`. Resolves the file kind to the
 * appropriate view using the closures captured by
 * `buildDefaultDecisionDeps`:
 *
 *   - `modified` → unified diff (`diff -u <fromAbs> <toAbs>`) with the
 *      existing fallback when the system `diff` CLI is missing.
 *   - `added`    → just print the new file's contents (there's nothing
 *      to diff against).
 *   - `removed`  → print the file that would be deleted (or a notice
 *      when it's already gone from disk).
 *
 * Errors reading individual files are logged as warnings and the preview
 * returns an empty string — the decision layer swallows the empty
 * response and proceeds to the prompt. This matches requirement #5 of
 * the diff-preview wiring (render failure must not block the prompt).
 */
async function defaultRenderUnifiedDiffForEntry(
  relPath: string,
  kind: FileKind,
  ctx: {
    target: string;
    assetsRoot: string;
    which: (cmd: string) => string | null;
    execCapture: typeof defaultExecCapture;
  },
): Promise<string> {
  if (kind === "modified") {
    const fromAbs = join(ctx.target, relPath);
    const toAbs = join(ctx.assetsRoot, relPath);
    return defaultRenderUnifiedDiff(relPath, fromAbs, toAbs, {
      which: ctx.which,
      execCapture: ctx.execCapture,
    });
  }
  if (kind === "added") {
    const toAbs = join(ctx.assetsRoot, relPath);
    logger.info(`--- new file ${relPath} ---`);
    let content: string;
    try {
      content = readFileSync(toAbs, "utf-8");
    } catch (error) {
      logger.warn(
        `could not read new version of ${relPath}: ${
          error instanceof Error ? error.message : String(error)
        } — skipping preview`,
      );
      return "";
    }
    // Every line is an addition — render in green to match git's colour.
    for (const line of content.split(/\r?\n/)) console.log(pc.green(line));
    return content;
  }
  // kind === "removed"
  const oldAbs = join(ctx.target, relPath);
  logger.info(`--- ${relPath} (no longer exists in new version) ---`);
  try {
    const content = readFileSync(oldAbs, "utf-8");
    logger.info("Current content (would be removed when --prune is in effect):");
    // Whole-file removal preview — red mirrors git's `diff --old-only` view.
    for (const line of content.split(/\r?\n/)) console.log(pc.red(line));
    return content;
  } catch {
    logger.info("(this file no longer exists on disk either)");
    return "";
  }
}

export { defaultRenderUnifiedDiffForEntry };

/**
 * Open the user's editor on the current file and return whatever they
 * saved. Falls back to logging a warning and returning an empty string
 * (which `resolveUpgradeActions` treats as "keep my version") if the editor
 * is missing or exits non-zero.
 *
 * We pass `waitForUserInput: true` so the prompt does not return until the
 * user closes their editor — without this, @inquirer/editor would resolve
 * immediately with the unchanged default and the user would see nothing
 * happen.
 */
async function defaultOpenEditor(
  relPath: string,
  target: string,
  assetsRoot: string,
): Promise<string> {
  const currentPath = join(target, relPath);
  const newPath = join(assetsRoot, relPath);
  let current = "";
  try {
    current = readFileSync(currentPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read current version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  let incoming = "";
  try {
    incoming = readFileSync(newPath, "utf-8");
  } catch (error) {
    logger.warn(
      `could not read new version of ${relPath}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  logger.info(`--- editing ${relPath} ---`);
  logger.info("New version from assets:");
  for (const line of incoming.split(/\r?\n/)) logger.info(line);
  logger.info("--- end of new version; opening $EDITOR with current content as default ---");

  try {
    const edited = await editor({
      message: `Edit ${relPath} (close the editor when done; an empty file means "keep my version")`,
      default: current,
      postfix: ".md",
      waitForUserInput: true,
    });
    return edited;
  } catch (error) {
    logger.warn(
      `editor failed for ${relPath}: ${error instanceof Error ? error.message : String(error)} — keeping current version`,
    );
    return "";
  }
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

import { createHash } from "node:crypto";
import type { DiffPlan, PkgInclude } from "../lib/diff.js";
import { logger } from "../lib/logger.js";

/**
 * Pure coordination layer for `pisquad upgrade`.
 *
 * `resolveUpgradeActions` decides, for every entry in the `DiffPlan`,
 * whether the file should be:
 *
 *   - `adopt`        → copied from assets into the target (with backup first
 *                      for `modified`/`removed` that already exist on disk).
 *   - `keep`         → left untouched on disk. Used both for user-chosen
 *                      "keep my edits" picks and for `removed` entries when
 *                      `--prune` is not in play.
 *   - `edit`         → user opened `$EDITOR`, merged manually; the resulting
 *                      content is written back after copy and the file is
 *                      backed up (it contains the user's pre-edit version).
 *
 * The function is intentionally free of `inquirer` / `fs` / `child_process`
 * calls so it is unit-testable with fake `DecisionDeps`. The default
 * implementation lives in `decision-defaults.ts` and wires up the real
 * prompts + `diff` / editor.
 */

/** Kind of change the package is making to a file in the target. */
export type FileKind = "modified" | "added" | "removed";

/** User-confirmed outcome for a single file. */
export type FileDecision = "adopt" | "keep" | "edit";

/** Top-level strategy picked by the user before per-file decisions begin. */
export type StrategyMode = "all-adopt" | "all-keep" | "per-file";

/** A single entry in the plan, augmented with the include's interactive flag. */
export interface PlanEntry {
  relPath: string;
  kind: FileKind;
  fromHash?: string;
  toHash?: string;
  /** True when the include owning this file is user-editable territory. */
  interactive: boolean;
}

/** Result of a per-file `edit` decision. */
export interface EditResult {
  relPath: string;
  content: string;
  /**
   * True when the user saved content whose hex digest equals the new assets
   * version's hash. Surfaced in the upgrade summary so the user can see that
   * their edit collapsed back to "adopt new".
   */
  matchesTheirs: boolean;
}

/**
 * The aggregated output of the decision layer. Consumed by the upgrade
 * command to drive backup, copy, prune, edit-write-back, and summary.
 *
 * Sets partition the plan's file paths by intent:
 *
 *   - `entries`   — per-interactive-file decision map (excludes managed files).
 *   - `adopt`     — files whose content should be copied from assets (the
 *                   union of "managed modified/added" and "interactive adopt"
 *                   decisions, minus files handled by `editResults`).
 *   - `keep`      — files to leave alone. The copy filter MUST skip these
 *                   so the user's local copy survives.
 *   - `remove`    — files to delete (only populated when `--prune` is set and
 *                   the user confirmed the deletion).
 *   - `backup`    — files that must be archived before any write or delete.
 *                   Includes all `modified` + `removed` that exist on disk,
 *                   plus every `edit` file (whose tar contains the user's
 *                   pre-edit version).
 *   - `editResults` — write-back list, processed after copy so the staged
 *                   copy is overwritten with the user-edited content.
 */
export interface ResolvedPlan {
  entries: Map<string, FileDecision>;
  adopt: Set<string>;
  keep: Set<string>;
  remove: Set<string>;
  backup: Set<string>;
  editResults: EditResult[];
  mode: StrategyMode;
}

/** Inputs the caller must supply to drive a decision. */
export interface DecisionInput {
  plan: DiffPlan;
  includes: PkgInclude[];
  /**
   * The install target root. Required so the default adapter can read
   * `current` content for `edit` decisions. Decision.ts itself never reads
   * files; this field is forwarded to the adapter via `deps`.
   */
  target: string;
  prune: boolean;
  /**
   * Narrowed form of the raw `--interactive` / `--no-interactive` flag as
   * seen by the decision layer. The call site in `upgradeCommand` always
   * passes `options.interactive === true`, so the three meaningful values
   * reaching this layer are:
   *
   *   - `true`  → user passed `--interactive` (explicit opt-in).
   *   - `false` → EITHER the user passed `--no-interactive`, OR they
   *               passed no flag at all. These two cases are NOT
   *               distinguishable from this field alone; consult
   *               `interactiveSetByUser` to tell them apart. The
   *               decision logic in `shouldPrompt` does so explicitly.
   *
   * Combined with `isInteractiveEnv` and `yes` to decide whether any
   * prompt is fired.
   */
  interactive: boolean;
  /**
   * True when the user explicitly passed `--interactive` or `--no-interactive`.
   * Used so we can decide whether a non-interactive run was a deliberate
   * "I want batch behaviour" choice vs. a fallback from missing tty.
   */
  interactiveSetByUser: boolean;
  /** TTY + non-CI check from env.isInteractive(). */
  isInteractiveEnv: boolean;
  /** True when -y / --yes was passed; always suppresses prompts. */
  yes?: boolean;
}

/**
 * Test seam — every prompt, renderer, editor, env lookup, and hash function
 * is injectable. Production code calls `buildDefaultDecisionDeps()` from
 * `decision-defaults.ts`; tests pass fakes that record calls and return
 * scripted answers.
 */
export interface DecisionDeps {
  promptStrategy?: () => Promise<StrategyMode>;
  promptFileDecision?: (
    entry: PlanEntry,
    remaining: number,
    kind: FileKind,
  ) => Promise<FileDecision | "__adopt-all" | "__keep-all">;
  /**
   * Render the unified diff (or contents) for one interactive entry BEFORE
   * `promptFileDecision` is shown, so the user always sees what they're
   * about to decide on. The default adapter in `decision-defaults.ts`
   * resolves the absolute paths itself from the closures captured by
   * `buildDefaultDecisionDeps`; this layer only knows about `relPath` and
   * the file's `kind`.
   *
   *   - `modified` → unified diff from current to new.
   *   - `added`    → show the new file's full content.
   *   - `removed`  → show the file that would be deleted (or a notice).
   *
   * Optional — when not supplied (e.g. test deps that don't need the
   * preview) the diff step is silently skipped. Failures inside the
   * renderer are also swallowed (logged as a warn) so a missing-file
   * read or a system-`diff` crash never blocks the prompt path.
   */
  renderUnifiedDiff?: (relPath: string, kind: FileKind) => Promise<string>;
  /**
   * Open an editor on the user's copy of `relPath` and return the merged
   * content. The default adapter in `decision-defaults.ts` reads
   * `currentContent` from `<target>/<relPath>` and `newContent` from
   * `<assetsRoot>/<relPath>` itself; the empty-string sentinels from
   * `decision.ts` are placeholders the adapter ignores.
   */
  openEditor?: (relPath: string, currentContent: string, newContent: string) => Promise<string>;
  env?: NodeJS.ProcessEnv;
  sha256Content?: (content: string) => string;
}

/** Default SHA-256 hex of an in-memory string. */
function defaultSha256Content(content: string): string {
  return createHash("sha256").update(content, "utf-8").digest("hex");
}

/** Find the include that owns a target-relative path. */
function findInclude(includes: PkgInclude[], relPath: string): PkgInclude | undefined {
  // Match from longest targetSubPath first so ".pi/extensions/codegraph" wins
  // over ".pi" if both were ever registered. We don't currently do that, but
  // the sort makes the lookup robust against future changes.
  const sorted = [...includes].sort(
    (a, b) => b.targetSubPath.length - a.targetSubPath.length,
  );
  for (const inc of sorted) {
    if (!inc.targetSubPath) return inc;
    if (relPath === inc.targetSubPath) return inc;
    if (relPath.startsWith(`${inc.targetSubPath}/`)) return inc;
  }
  return undefined;
}

/**
 * Build the PlanEntry list from a DiffPlan + includes, flagging each entry
 * with the owning include's `interactive` setting.
 *
 * The diff's `fromHash` / `toHash` are preserved as-is so the decision layer
 * can reason about whether a file even exists on disk (removed) or in assets
 * (added).
 */
function entriesFromPlan(plan: DiffPlan, includes: PkgInclude[]): PlanEntry[] {
  const entries: PlanEntry[] = [];
  for (const m of plan.modified) {
    const inc = findInclude(includes, m.relPath);
    entries.push({
      relPath: m.relPath,
      kind: "modified",
      fromHash: m.fromHash,
      toHash: m.toHash,
      interactive: inc?.interactive === true,
    });
  }
  for (const a of plan.added) {
    const inc = findInclude(includes, a.relPath);
    entries.push({
      relPath: a.relPath,
      kind: "added",
      toHash: a.toHash,
      interactive: inc?.interactive === true,
    });
  }
  for (const r of plan.removed) {
    const inc = findInclude(includes, r.relPath);
    entries.push({
      relPath: r.relPath,
      kind: "removed",
      fromHash: r.fromHash,
      interactive: inc?.interactive === true,
    });
  }
  // Keep the same order plan.modified/added/removed are sorted in (by relPath
  // alphabetically within each bucket) so per-file prompts are deterministic.
  return entries;
}

/**
 * Decide whether we should prompt the user at all. Three independent
 * suppressors short-circuit to the "no prompts → all-adopt" default:
 *
 *   1. `yes === true` (`--yes`).
 *   2. `interactiveSetByUser === true && interactive === false` (explicit
 *      `--no-interactive`).
 *   3. `isInteractiveEnv === false` (no tty / CI / PISQUAD_NO_TTY).
 *
 * When `interactiveSetByUser === false`, the caller-narrowed
 * `interactive === false` means the flag was absent, not that the user opted
 * out. If a tty is available, that combination proceeds to the interactive
 * flow; this is the implicit-interactive path required by ADR-0003 §5.
 */
function shouldPrompt(input: DecisionInput): boolean {
  if (input.yes === true) return false;
  // Only an EXPLICIT `--no-interactive` is treated as opt-out. When
  // the user did not pass the flag, `interactive` arrives as `false`
  // (the caller narrows via `options.interactive === true`); in that
  // case we must still consult `isInteractiveEnv` so a real tty
  // triggers the interactive flow per ADR-0003 §5.
  if (input.interactiveSetByUser && input.interactive === false) return false;
  return input.isInteractiveEnv;
}

/**
 * Compute the upgrade's action plan.
 *
 * The function is intentionally free of side effects beyond the supplied
 * `deps`. It does NOT read files, spawn editors, or write anything. Real I/O
 * is funnelled through `deps` so tests can drive every branch deterministically.
 */
export async function resolveUpgradeActions(
  input: DecisionInput,
  deps: DecisionDeps = {},
): Promise<ResolvedPlan> {
  const sha256Content = deps.sha256Content ?? defaultSha256Content;

  const empty: ResolvedPlan = {
    entries: new Map(),
    adopt: new Set(),
    keep: new Set(),
    remove: new Set(),
    backup: new Set(),
    editResults: [],
    mode: "all-adopt",
  };

  const allEntries = entriesFromPlan(input.plan, input.includes);
  if (allEntries.length === 0) return empty;

  const interactiveEntries = allEntries.filter((e) => e.interactive);
  const managedEntries = allEntries.filter((e) => !e.interactive);

  // 1. Managed (non-interactive) entries follow the legacy behaviour: modified
  //    overwrites (the legacy code path also backs them up), added copies, and
  //    removed is kept unless --prune is in play. None of these depend on the
  //    user-facing prompts, so we resolve them up front.
  for (const entry of managedEntries) {
    switch (entry.kind) {
      case "modified":
        empty.adopt.add(entry.relPath);
        empty.backup.add(entry.relPath);
        break;
      case "added":
        empty.adopt.add(entry.relPath);
        break;
      case "removed":
        if (input.prune) {
          empty.remove.add(entry.relPath);
          empty.backup.add(entry.relPath);
        } else {
          empty.keep.add(entry.relPath);
        }
        break;
    }
  }

  // 2. If there are no interactive entries, we're done. This is the common
  //    case for projects that only have extension-channel updates, and it
  //    keeps the upgrade behaviour identical to the pre-interactive version.
  if (interactiveEntries.length === 0) return empty;

  // 3. Decide the strategy. When we cannot prompt, default to all-adopt — that
  //    matches the legacy "no-tty → batch overwrite" behaviour and is also the
  //    command's documented non-interactive fallback.
  let mode: StrategyMode;
  if (!shouldPrompt(input)) {
    mode = "all-adopt";
  } else if (deps.promptStrategy === undefined) {
    // Should not happen in practice (the default deps always supply it), but
    // guard so the function is safe to call with `deps = {}`.
    mode = "all-adopt";
  } else {
    mode = await deps.promptStrategy();
  }
  empty.mode = mode;

  // 4. Apply the strategy to interactive entries.
  if (mode === "all-adopt") {
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          empty.backup.add(entry.relPath);
          break;
        case "added":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          break;
        case "removed":
          // With --prune, "all-adopt" means "delete the file". The user's
          // intent is clear: they accepted the upgrade plan and want every
          // stale file gone. Without --prune we keep the file — the legacy
          // behaviour for "no prune" survives.
          if (input.prune) {
            empty.entries.set(entry.relPath, "adopt");
            empty.remove.add(entry.relPath);
            empty.backup.add(entry.relPath);
          } else {
            empty.entries.set(entry.relPath, "keep");
            empty.keep.add(entry.relPath);
          }
          break;
      }
    }
    return empty;
  }

  if (mode === "all-keep") {
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
        case "added":
        case "removed":
          empty.entries.set(entry.relPath, "keep");
          empty.keep.add(entry.relPath);
          break;
      }
    }
    return empty;
  }

  // 5. per-file: walk the entries in deterministic order, ask the user, and
  //    honour batch shortcuts that fan out to remaining entries.
  if (deps.promptFileDecision === undefined || deps.openEditor === undefined) {
    // Same fallback as above — if the caller asked for per-file but didn't
    // wire the prompt functions, we degrade to all-adopt rather than throw.
    for (const entry of interactiveEntries) {
      switch (entry.kind) {
        case "modified":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          empty.backup.add(entry.relPath);
          break;
        case "added":
          empty.entries.set(entry.relPath, "adopt");
          empty.adopt.add(entry.relPath);
          break;
        case "removed":
          if (input.prune) {
            empty.entries.set(entry.relPath, "adopt");
            empty.remove.add(entry.relPath);
            empty.backup.add(entry.relPath);
          } else {
            empty.entries.set(entry.relPath, "keep");
            empty.keep.add(entry.relPath);
          }
          break;
      }
    }
    return empty;
  }

  // Walk the interactive entries; track remaining = how many entries the user
  // has not yet seen, so batch shortcuts can advertise "Adopt all remaining
  // (N)". Index-based loop because we break out via the batch shortcuts.
  for (let i = 0; i < interactiveEntries.length; i++) {
    const entry = interactiveEntries[i]!;
    const remaining = interactiveEntries.length - i - 1;
    // `removed` entries without --prune cannot actually be deleted, so
    // prompting the user about a Delete/Keep choice would only produce
    // confusing no-ops. Auto-apply keep (matching the strategy-default and
    // managed-entry paths) and skip the prompt (and its diff preview)
    // entirely.
    if (entry.kind === "removed" && !input.prune) {
      empty.entries.set(entry.relPath, "keep");
      empty.keep.add(entry.relPath);
      continue;
    }
    // Render the file's diff / preview BEFORE firing the prompt, so the
    // user is never asked to choose blindly. Best-effort: if the dep is
    // missing (common in tests) we skip; if it throws we warn and fall
    // through to the prompt so the upgrade flow is never blocked.
    if (deps.renderUnifiedDiff !== undefined) {
      try {
        await deps.renderUnifiedDiff(entry.relPath, entry.kind);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        logger.warn(
          `could not render diff for ${entry.relPath}: ${message} — skipping preview, proceeding to prompt`,
        );
      }
    }
    const answer = await deps.promptFileDecision(entry, remaining, entry.kind);
    if (answer === "__adopt-all" || answer === "__keep-all") {
      // Resolve the current entry with the batch decision, then fill the rest.
      const decision: FileDecision = answer === "__adopt-all" ? "adopt" : "keep";
      await applyInteractiveDecision(empty, entry, decision, deps, sha256Content, input.prune);
      for (let j = i + 1; j < interactiveEntries.length; j++) {
        await applyInteractiveDecision(
          empty,
          interactiveEntries[j]!,
          decision,
          deps,
          sha256Content,
          input.prune,
        );
      }
      return empty;
    }
    await applyInteractiveDecision(empty, entry, answer, deps, sha256Content, input.prune);
  }
  return empty;
}

/** Apply a single per-file decision to the in-progress plan. */
async function applyInteractiveDecision(
  plan: ResolvedPlan,
  entry: PlanEntry,
  decision: FileDecision,
  deps: DecisionDeps,
  sha256Content: (content: string) => string,
  prune: boolean,
): Promise<void> {
  plan.entries.set(entry.relPath, decision);
  if (decision === "keep") {
    plan.keep.add(entry.relPath);
    return;
  }
  if (decision === "adopt") {
    if (entry.kind === "removed") {
      // "adopt" for a removed file = "delete this file". Only honourable
      // when --prune is in play; otherwise we silently keep the user's copy
      // (the prompt defaults "Adopt" for removed entries to mean "delete",
      // so the user expects this behaviour even though their pick is
      // effectively no-op'd without --prune).
      if (prune) {
        plan.remove.add(entry.relPath);
        plan.backup.add(entry.relPath);
      } else {
        plan.keep.add(entry.relPath);
      }
      return;
    }
    plan.adopt.add(entry.relPath);
    if (entry.kind === "modified") {
      plan.backup.add(entry.relPath);
    }
    return;
  }
  // decision === "edit": invoke the editor via deps. openEditor is guaranteed
  // to exist here because the caller only enters per-file mode when it does.
  // (resolveUpgradeActions short-circuits to all-adopt otherwise.)
  const openEditor = deps.openEditor!;
  // currentContent / newContent are filled by the default adapter; tests can
  // supply a stub that ignores them and returns a canned string.
  const edited = await openEditor(entry.relPath, "", "");
  if (edited.length === 0) {
    // Empty editor result → treat as "keep my version". Surface this via
    // entries map (already set) and skip backup; the file is left alone.
    plan.keep.add(entry.relPath);
    return;
  }
  const matchesTheirs = typeof entry.toHash === "string" && sha256Content(edited) === entry.toHash;
  plan.editResults.push({ relPath: entry.relPath, content: edited, matchesTheirs });
  plan.backup.add(entry.relPath);
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import {
  defaultRenderUnifiedDiff,
  defaultRenderUnifiedDiffForEntry,
} from "../../src/upgrade/decision-defaults.js";

/**
 * `renderUnifiedDiff` must keep working when the system `diff` CLI is
 * absent (CI sandboxes, alpine base images, etc.). We force the fallback by
 * injecting a `which` stub that returns null, and verify the function
 * still returns the new version's content for downstream consumption.
 */
describe("defaultRenderUnifiedDiff", () => {
  it("falls back to readFileSync when diff CLI is missing", async () => {
    const fromAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-from-")), "a.md");
    const toAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-to-")), "b.md");
    const newContent = "new line one\nnew line two\n";
    writeFileSync(fromAbs, "old line one\nold line two\n", "utf-8");
    writeFileSync(toAbs, newContent, "utf-8");

    const result = await defaultRenderUnifiedDiff("docs/example.md", fromAbs, toAbs, {
      which: () => null,
      execCapture: async () => {
        throw new Error("execCapture must not be called when diff is missing");
      },
    });
    assert.equal(result, newContent, "fallback returns the new file's content");
  });

  it("uses diff CLI when available and returns its stdout", async () => {
    const fromAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-from2-")), "a.md");
    const toAbs = join(mkdtempSync(join(tmpdir(), "pisquad-diff-to2-")), "b.md");
    writeFileSync(fromAbs, "old\n", "utf-8");
    writeFileSync(toAbs, "new\n", "utf-8");

    const fakeDiffOutput = "--- a\n+++ b\n-old\n+new";
    const result = await defaultRenderUnifiedDiff("docs/example.md", fromAbs, toAbs, {
      which: () => "/usr/bin/diff",
      execCapture: async () => ({ stdout: fakeDiffOutput, stderr: "", exitCode: 1 }),
    });
    assert.equal(result, fakeDiffOutput);
  });

  it("returns empty string when diff says files are identical", async () => {
    const tmp = mkdtempSync(join(tmpdir(), "pisquad-diff-same-"));
    const a = join(tmp, "a.md");
    const b = join(tmp, "b.md");
    const content = "same content\n";
    writeFileSync(a, content, "utf-8");
    writeFileSync(b, content, "utf-8");
    const result = await defaultRenderUnifiedDiff("same.md", a, b, {
      which: () => "/usr/bin/diff",
      execCapture: async () => ({ stdout: "", stderr: "", exitCode: 0 }),
    });
    assert.equal(result, "", "identical files → empty stdout");
  });
});

/**
 * `defaultRenderUnifiedDiffForEntry` is the kind-aware adapter wired into
 * `buildDefaultDecisionDeps`. It receives only `relPath` + `kind` (the
 * signatures the decision layer can safely pass without breaking the pure-
 * coordination contract) and resolves absolute paths itself. These tests
 * exercise every branch and the missing-file warning path.
 */
describe("defaultRenderUnifiedDiffForEntry", () => {
  // Helper: write a file under `root/relPath`, creating parent dirs as needed.
  function writeUnder(root: string, relPath: string, content: string): void {
    const abs = join(root, relPath);
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content, "utf-8");
  }

  it("modified: uses diff CLI between <target>/<relPath> and <assetsRoot>/<relPath>", async () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-diffentry-tgt-"));
    const assetsRoot = mkdtempSync(join(tmpdir(), "pisquad-diffentry-ast-"));
    const relPath = "docs/example.md";
    writeUnder(target, relPath, "old\n");
    writeUnder(assetsRoot, relPath, "new\n");

    const fakeStdout = "--- a\n+++ b\n-old\n+new";
    const calls: string[][] = [];
    const result = await defaultRenderUnifiedDiffForEntry(relPath, "modified", {
      target,
      assetsRoot,
      which: () => "/usr/bin/diff",
      execCapture: async (_cmd, args) => {
        calls.push(args);
        return { stdout: fakeStdout, stderr: "", exitCode: 1 };
      },
    });
    assert.equal(result, fakeStdout);
    assert.deepEqual(calls[0], ["-u", join(target, relPath), join(assetsRoot, relPath)]);
  });

  it("added: returns new file content even without the diff CLI", async () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-diffentry-tgt2-"));
    const assetsRoot = mkdtempSync(join(tmpdir(), "pisquad-diffentry-ast2-"));
    const relPath = "docs/brand-new.md";
    const newContent = "completely fresh file content\n";
    writeUnder(assetsRoot, relPath, newContent);

    const result = await defaultRenderUnifiedDiffForEntry(relPath, "added", {
      target,
      assetsRoot,
      which: () => null,
      // execCapture must NOT be invoked when kind !== "modified".
      execCapture: async () => {
        throw new Error("execCapture must not be called for added entries");
      },
    });
    assert.equal(result, newContent, "added entries return the new file content");
  });

  it("added: missing assets file → logs warn, returns empty string", async () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-diffentry-tgt3-"));
    const assetsRoot = mkdtempSync(join(tmpdir(), "pisquad-diffentry-ast3-"));
    // Don't write the assets file.
    const warnings: string[] = [];
    const originalWarn = console.warn;
    console.warn = (...args: unknown[]) => {
      warnings.push(args.map(String).join(" "));
    };
    try {
      const result = await defaultRenderUnifiedDiffForEntry(
        "docs/missing.md",
        "added",
        {
          target,
          assetsRoot,
          which: () => null,
          execCapture: async () => {
            throw new Error("must not run");
          },
        },
      );
      assert.equal(result, "", "missing file → empty preview");
      assert.equal(
        warnings.some((w) => w.includes("skipping preview")),
        true,
        "warn logged so the user knows the diff was skipped",
      );
    } finally {
      console.warn = originalWarn;
    }
  });

  it("removed: shows current content when file still exists on disk", async () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-diffentry-tgt4-"));
    const assetsRoot = mkdtempSync(join(tmpdir(), "pisquad-diffentry-ast4-"));
    const relPath = "docs/legacy.md";
    const oldContent = "stale user content\n";
    writeUnder(target, relPath, oldContent);

    const result = await defaultRenderUnifiedDiffForEntry(relPath, "removed", {
      target,
      assetsRoot,
      which: () => null,
      execCapture: async () => {
        throw new Error("must not run for removed entries");
      },
    });
    assert.equal(result, oldContent, "removed entries return the current content");
  });

  it("removed: missing target file → logs informational note, returns empty string", async () => {
    const target = mkdtempSync(join(tmpdir(), "pisquad-diffentry-tgt5-"));
    const assetsRoot = mkdtempSync(join(tmpdir(), "pisquad-diffentry-ast5-"));
    const infos: string[] = [];
    const originalLog = console.log;
    console.log = (...args: unknown[]) => {
      infos.push(args.map(String).join(" "));
    };
    try {
      const result = await defaultRenderUnifiedDiffForEntry(
        "docs/ghost.md",
        "removed",
        {
          target,
          assetsRoot,
          which: () => null,
          execCapture: async () => {
            throw new Error("must not run for removed entries");
          },
        },
      );
      assert.equal(result, "", "missing file → empty preview");
      assert.equal(
        infos.some((line) => line.includes("no longer exists on disk")),
        true,
        "user sees a clear note when the file is already gone",
      );
    } finally {
      console.log = originalLog;
    }
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  mkdtempSync,
  writeFileSync,
  readFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  unlinkSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname, sep } from "node:path";
import { execSync } from "node:child_process";
import { ExitPromptError } from "@inquirer/core";
import { upgradeCommand } from "../../src/commands/upgrade.js";
import { writeState, readAssetsVersion, readCliVersion } from "../../src/lib/version.js";
import type { Channels } from "../../src/lib/ui.js";
import { resolveAsset } from "../../src/lib/paths.js";
import type { DecisionDeps } from "../../src/upgrade/decision.js";

/**
 * Integration test that exercises the full upgrade pipeline with fake
 * `DecisionDeps`. We construct a synthetic install target tree, write a
 * state.json, then call `upgradeCommand` with the decision deps overridden
 * to drive every decision branch.
 *
 * The test deliberately does NOT depend on a global `tar` invocation
 * beyond what is already required by `createBackup` — if `tar` is missing
 * the relevant assertions skip rather than fail, so the test passes on
 * hosts without tar.
 */

function tarAvailable(): boolean {
  try {
    execSync("tar --version", { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

/** Logged once per test run when tar is missing, so skipped tests are
 * visible in CI output rather than silently passing. */
let tarSkipReasonLogged = false;
function noteTarSkipIfNeeded(): void {
  if (tarSkipReasonLogged) return;
  tarSkipReasonLogged = true;
  // eslint-disable-next-line no-console
  console.log("# skip: tar not available — backup-dependent integration tests");
}

function makeTempTarget(): string {
  return mkdtempSync(join(tmpdir(), "pisquad-upgrade-int-"));
}

/**
 * Populate a fresh target with:
 *   - a valid state.json (so upgradeCommand doesn't bail)
 *   - the assets-version/channels baseline (matching what's currently shipped)
 *
 * Returns the target root. The target's content mirrors what an install
 * created via `pisquad install` would produce, but only for the subtrees
 * we want to test against.
 */
function seedTarget(target: string, channels: Channels): void {
  writeState(target, { channels });
}

interface DecisionLog {
  promptStrategyCalls: number;
  promptFileDecisionCalls: number;
  openEditorCalls: number;
  entriesSeen: Array<{ relPath: string; kind: string }>;
}

function makeDeps(
  strategyAnswer: "all-adopt" | "all-keep" | "per-file" = "per-file",
  answers: Array<{ match: string; answer: "adopt" | "keep" | "edit" }> = [],
  edits: Map<string, string> = new Map(),
): { deps: DecisionDeps; log: DecisionLog } {
  const log: DecisionLog = {
    promptStrategyCalls: 0,
    promptFileDecisionCalls: 0,
    openEditorCalls: 0,
    entriesSeen: [],
  };
  const deps: DecisionDeps = {
    promptStrategy: async () => {
      log.promptStrategyCalls += 1;
      return strategyAnswer;
    },
    promptFileDecision: async (entry, remaining, kind) => {
      log.promptFileDecisionCalls += 1;
      log.entriesSeen.push({ relPath: entry.relPath, kind });
      void remaining;
      void kind;
      // Find the first rule whose `match` substring appears in the relPath;
      // fall through to "keep" if nothing matches (matches the existing
      // semantics for an empty/unmatched answers list).
      for (const rule of answers) {
        if (entry.relPath.includes(rule.match)) return rule.answer;
      }
      return "keep";
    },
    openEditor: async (relPath, _current, _new) => {
      log.openEditorCalls += 1;
      return edits.get(relPath) ?? `edited-${relPath}`;
    },
    sha256Content: (content: string) => {
      // Simple stable hash so matchesTheirs works deterministically.
      let h = 0;
      for (let k = 0; k < content.length; k++) h = ((h << 5) - h + content.charCodeAt(k)) | 0;
      return h.toString(16);
    },
  };
  return { deps, log };
}

/**
 * Touch a file at target/relPath by reading from the assets root (or
 * returning a literal if no assets content is available). Useful to set
 * up "user-modified" content that differs from assets.
 */
function writeUserFile(target: string, relPath: string, content: string): void {
  const abs = join(target, relPath);
  mkdirSync(dirname(abs), { recursive: true });
  writeFileSync(abs, content, "utf-8");
}

function readTarget(target: string, relPath: string): string {
  return readFileSync(join(target, relPath), "utf-8");
}

function assetsRead(relPath: string): string {
  return readFileSync(resolveAsset(relPath), "utf-8");
}

describe("upgradeCommand integration", () => {
  it("interactive edit writes user content", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    } // skip on hosts without tar
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);
    // Seed the target with a user-modified version of an interactive file.
    // We modify docs/README.md so it differs from the assets version.
    const userContent = "# user-modified content\n\nThis is the user's own edits.\n";
    writeUserFile(target, "docs/README.md", userContent);
    // Also pre-create docs/conventions (matching assets layout — so the diff
    // recognises the target as a pisquad install).
    writeUserFile(target, "docs/conventions/install-state.md", "(irrelevant)");
    writeUserFile(target, ".pi/agents/worker.md", "(irrelevant)");

    const editedContent = "user merged content here";
    const edits = new Map([["docs/README.md", editedContent]]);
    const { deps, log } = makeDeps("per-file", [{ match: "docs/README.md", answer: "edit" }], edits);

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactiveSetByUser: true,
        // Force interactive by passing interactive=true (so shouldPrompt returns true).
        interactive: true,
        forceInteractiveEnv: true,
        // Bypass selfUpdate stage via env var; ignore any error from npm view.
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // The user's edited content must be on disk after upgrade.
    const finalContent = readTarget(target, "docs/README.md");
    assert.equal(finalContent, editedContent, "edited content wins");

    // Decision layer was actually invoked once.
    assert.equal(log.promptStrategyCalls, 1);
    assert.equal(log.openEditorCalls >= 1, true, "editor opened at least once");

    // Cleanup
    try {
      execSync(`rm -rf ${target}`, { stdio: "ignore" });
    } catch {
      /* best-effort */
    }
  });

  it("non-interactive: upgradeCommand adopts everything in interactive areas too (legacy behaviour)", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Seed the target with user-modified content for an interactive file.
    const userContent = "USER_EDIT_" + Date.now();
    writeUserFile(target, "docs/README.md", userContent);

    // interactive=false, isInteractiveEnv default false in tests → all-adopt
    const { deps, log } = makeDeps("all-adopt", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactive: false,
        interactiveSetByUser: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // After non-interactive upgrade, docs/README.md must match the assets
    // content (the user's edits were silently overwritten — that's the
    // documented legacy fallback behaviour).
    const finalContent = readTarget(target, "docs/README.md");
    const assetsContent = assetsRead("docs/README.md");
    assert.equal(finalContent, assetsContent, "non-interactive upgraded to assets content");
    assert.equal(log.promptStrategyCalls, 0, "no prompt in non-interactive mode");
  });

  it("managed extension files: always overwritten even in interactive mode", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Pre-create a file under a managed include (`.pi/extensions/subagent`)
    // with user-modified content. Managed includes are NEVER prompted —
    // the decision layer treats them as "always adopt" regardless of
    // strategy. The user's override must be overwritten.
    const targetFile = ".pi/extensions/subagent/index.ts";
    const userContent = "USER_OVERRIDE_" + Date.now();
    writeUserFile(target, targetFile, userContent);

    const { deps } = makeDeps("all-keep", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // The user's override must be gone — managed entries are always
    // overwritten regardless of the strategy the user picked.
    const finalContent = readTarget(target, targetFile);
    assert.equal(
      finalContent.includes("USER_OVERRIDE"),
      false,
      "managed file overwritten even when strategy=all-keep",
    );
    // Sanity check: the file is now the assets' content.
    const assetsContent = assetsRead(targetFile);
    assert.equal(finalContent, assetsContent, "managed file matches assets after upgrade");
  });

  it("prune=true: removed files adopted via all-adopt are deleted", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Create a file in the target that isn't in assets. We'll fabricate
    // an "assets diff" by writing into docs and then deleting it AFTER
    // upgrade computed its plan but BEFORE running. Instead, simulate by
    // simply having target contain a file the assets don't ship and
    // relying on the package diff to detect it as removed.
    //
    // Easier: create a real "removed" scenario by copying an asset, then
    // deleting it before upgrade.
    const targetOnlyRel = "docs/legacy-note.md";
    writeUserFile(target, targetOnlyRel, "legacy");

    const { deps } = makeDeps("all-adopt", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: true,
        decisionDeps: deps,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // The removed file should be gone from the target after --prune.
    assert.equal(existsSync(join(target, targetOnlyRel)), false, "prune removed the file");
  });

  it("decision layer throws (user cancelled): no backup, exit code 1", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Mark the file we want to keep so we can check it survives.
    const marker = "KEEP_ME_" + Date.now();
    writeUserFile(target, "docs/README.md", marker);

    const throwingDeps: DecisionDeps = {
      promptStrategy: async () => {
        throw new Error("user cancelled via Ctrl-C");
      },
    };

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: throwingDeps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      // restore — but capture
    }

    assert.equal(process.exitCode, 1, "exit code set to 1 on cancellation");

    // User content survived (no writes happened).
    const after = readTarget(target, "docs/README.md");
    assert.equal(after, marker, "user content preserved after cancel");

    // No backup tarball should exist (decision layer threw before backup).
    // Strict assertion: the backups dir must not exist at all, or if it
    // does (e.g. left over from a prior run) it must contain no .tar.gz
    // files. This catches regressions where the backup stage runs before
    // a failing decision layer.
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    if (existsSync(backupDir)) {
      const entries = readdirSync(backupDir);
      const tarballs = entries.filter((f) => f.endsWith(".tar.gz"));
      assert.equal(
        tarballs.length,
        0,
        `no .tar.gz files should exist after cancelled upgrade; found: ${tarballs.join(", ")}`,
      );
    }
    process.exitCode = prevExit;
  });

  it("decision layer throws ExitPromptError instance: cancel-aware branch, no backup, exit 1", async () => {
    // Reviewer W3 finding: the existing "decision layer throws" test
    // throws a plain Error and hits the "upgrade failed during decision"
    // branch. This test exercises the SECOND branch — a real
    // ExitPromptError from @inquirer/core — and proves that
    // upgradeCommand distinguishes the two by source and surfaces the
    // user-friendly "cancelled" message instead of the failure message.
    // Captures console.error output to verify the message split.
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    const marker = "KEEP_ME_" + Date.now();
    writeUserFile(target, "docs/README.md", marker);

    const exitErrorDeps: DecisionDeps = {
      promptStrategy: async () => {
        // Genuine ExitPromptError instance from @inquirer/core — what
        // user presses Ctrl-C actually raises inside the prompt layer.
        throw new ExitPromptError("User force closed the prompt with SIGINT");
      },
    };

    const errLines: string[] = [];
    const originalErr = console.error;
    console.error = (...args: unknown[]) => {
      errLines.push(args.map(String).join(" "));
    };

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: exitErrorDeps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      console.error = originalErr;
    }

    assert.equal(process.exitCode, 1, "exit code set to 1 on user cancel");

    // User content survived (no writes happened).
    const after = readTarget(target, "docs/README.md");
    assert.equal(after, marker, "user content preserved after cancel");

    // Cancel-aware branch printed "user cancelled" (NOT "upgrade failed
    // during decision"). The exitErrorDeps instance satisfies both the
    // `instanceof ExitPromptError` and the `error.name === "ExitPromptError"`
    // checks in upgrade.ts.
    const sawCancelMessage = errLines.some((line) => line.includes("user cancelled"));
    const sawFailureMessage = errLines.some((line) => line.includes("upgrade failed"));
    assert.equal(
      sawCancelMessage,
      true,
      `expected "user cancelled" branch; got: ${errLines.join(" | ")}`,
    );
    assert.equal(
      sawFailureMessage,
      false,
      `must NOT hit "upgrade failed during decision" branch for a real ExitPromptError`,
    );

    // No backup tarball should exist (decision layer threw before backup).
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    if (existsSync(backupDir)) {
      const entries = readdirSync(backupDir);
      const tarballs = entries.filter((f) => f.endsWith(".tar.gz"));
      assert.equal(
        tarballs.length,
        0,
        `no .tar.gz files should exist after a cancelled upgrade; found: ${tarballs.join(", ")}`,
      );
    }
    process.exitCode = prevExit;
  });

  it("decision layer throws { name: 'ExitPromptError' }: cancel-aware branch (name-based fallback)", async () => {
    // Reviewer W3 finding (secondary): upgradeCommand's cancel detection
    // has TWO checks — `instanceof ExitPromptError` AND `error.name ===
    // "ExitPromptError"` — for a reason. Sometimes the real class isn't
    // reachable (e.g. errors thrown across a worker boundary, errors
    // reconstructed from a serialized payload). This test exercises the
    // name-based fallback to make sure that path is also covered.
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);
    writeUserFile(target, "docs/README.md", "KEEP_ME_" + Date.now());

    const nameOnlyErrorDeps: DecisionDeps = {
      promptStrategy: async () => {
        // Plain Error object with the right name — NOT an instance of
        // @inquirer/core's ExitPromptError class. The double-check in
        // upgradeCommand must still treat this as a user cancellation.
        const error = new Error("user cancelled (name-only)");
        error.name = "ExitPromptError";
        throw error;
      },
    };

    const errLines: string[] = [];
    const originalErr = console.error;
    console.error = (...args: unknown[]) => {
      errLines.push(args.map(String).join(" "));
    };

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: nameOnlyErrorDeps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      console.error = originalErr;
    }

    assert.equal(process.exitCode, 1, "exit code set to 1 on user cancel (name-only)");
    const sawCancel = errLines.some((line) => line.includes("user cancelled"));
    const sawFailure = errLines.some((line) => line.includes("upgrade failed"));
    assert.equal(sawCancel, true, "name-based ExitPromptError still routes to cancel branch");
    assert.equal(
      sawFailure,
      false,
      "name-based ExitPromptError must NOT hit the upgrade failed branch",
    );
    process.exitCode = prevExit;
  });

  it("createBackup fails: exit 1, no changes made to target", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Set up a file that the diff will report as modified and that the
    // decision layer will mark for backup. We then sabotage the backup
    // by deleting the file from disk *between* the decision and the
    // createBackup call. The `promptFileDecision` hook fires after the
    // decision but before the upgrade command proceeds to backup, so
    // it's a convenient place to plant the failure.
    const marker = "KEEP_ME_" + Date.now();
    const targetFile = "docs/README.md";
    writeUserFile(target, targetFile, marker);

    const sabotagingDeps: DecisionDeps = {
      promptStrategy: async () => "per-file",
      promptFileDecision: async (_entry, _remaining, _kind) => {
        // Strip the file from disk AFTER the decision has already
        // recorded it for backup. createBackup validates every file
        // exists and will throw — the upgrade must catch that and exit
        // cleanly without touching anything else. Only sabotage once so
        // subsequent promptFileDecision calls don't trip over the
        // missing file (the editor hook reads from disk too).
        try {
          unlinkSync(join(target, targetFile));
          return "adopt";
        } catch {
          // Already gone — fall through to a safe answer.
          return "keep";
        }
      },
      openEditor: async () => "edited-fallback",
    };

    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: sabotagingDeps,
        interactive: true,
        interactiveSetByUser: true,
        forceInteractiveEnv: true,
        noSelf: true,
      });
    } finally {
      /* restore later */
    }

    assert.equal(process.exitCode, 1, "exit code set to 1 on backup failure");
    // No backup should exist (the createBackup call threw before any
    // tarball was written, and the upgrade must bail before the copy
    // stage).
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    if (existsSync(backupDir)) {
      const entries = readdirSync(backupDir);
      const tarballs = entries.filter((f) => f.endsWith(".tar.gz"));
      assert.equal(
        tarballs.length,
        0,
        `no .tar.gz files should exist after backup failure; found: ${tarballs.join(", ")}`,
      );
    }
    process.exitCode = prevExit;
  });

  it("dry-run: shows decision preview summary, never writes backup", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Seed a file so the diff has something to show — we want the
    // decision preview line, not the empty-plan fast path.
    const marker = "USER_CONTENT_" + Date.now();
    writeUserFile(target, "docs/README.md", marker);

    const { deps } = makeDeps("all-keep", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        dryRun: true,
        decisionDeps: deps,
        interactive: false,
        interactiveSetByUser: true,
        noSelf: true,
      });
    } finally {
      process.exitCode = prevExit;
    }

    // User content survives — dry-run must not touch the target.
    const after = readTarget(target, "docs/README.md");
    assert.equal(after, marker, "user content preserved after dry-run");
    // No backup should exist — dry-run never calls createBackup.
    const backupDir = join(target, ".pi", ".pisquad", "backups");
    assert.equal(existsSync(backupDir), false, "no backups dir created in dry-run");
    // The decision preview must have been printed (via console.log because
    // logger.info is hard to mock from outside the module). node:test
    // captures console output by default; we just assert dry-run
    // completed without throwing and the target is intact.
  });

  it("--interactive with no tty: emits a warning that interactive was ignored", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
      return;
    }
    const target = makeTempTarget();
    const channels: Channels = { core: true, codegraph: false, entire: false };
    seedTarget(target, channels);

    // Seed a file so the diff is non-empty (so the upgrade reaches the
    // decision / apply stages instead of just printing "no changes").
    writeUserFile(target, "docs/README.md", "user");

    const { deps } = makeDeps("all-adopt", []);
    // Capture warn output so we can assert on the W1 message.
    const originalWarn = console.warn;
    const warnings: string[] = [];
    console.warn = (...args: unknown[]) => {
      warnings.push(args.map(String).join(" "));
    };
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
        target,
        prune: false,
        decisionDeps: deps,
        // User explicitly asked for --interactive; we simulate a host
        // with no tty by NOT setting forceInteractiveEnv.
        interactive: true,
        interactiveSetByUser: true,
        noSelf: true,
      });
    } finally {
      console.warn = originalWarn;
      process.exitCode = prevExit;
    }

    const sawWarning = warnings.some((w) => w.includes("--interactive ignored"));
    assert.equal(
      sawWarning,
      true,
      `expected --interactive ignored warning, got: ${warnings.join(" | ")}`,
    );
  });
});

