4	export interface CopyOptions {
5	  filter?: (source: string, relativePath: string) => boolean;
6	  dryRun?: boolean;
7	  /**
8	   * Called once per entry that is intentionally skipped. Callers can use
9	   * this to surface warnings (e.g. symlinks in the asset tree, which we
10	   * deliberately do not follow during a recursive copy).
11	   */
12	  onSkip?: (relativePath: string, reason: string) => void;
13	}
14	
15	/** Recursively copy a directory, optionally filtering entries or running as a preview. */
16	export function copyDir(src: string, dest: string, options: CopyOptions = {}): void {
17	  const copy = (sourceDir: string, destinationDir: string, relativeDir: string): void => {
18	    for (const entry of readdirSync(sourceDir)) {
19	      const source = join(sourceDir, entry);
20	      const entryRelativePath = relativeDir ? join(relativeDir, entry) : entry;
21	      if (options.filter && !options.filter(source, entryRelativePath)) continue;
22	
23	      const stat = lstatSync(source);
24	      // Symlinks are skipped (not followed, not copied). Following them could
25	      // escape the source tree or copy a target that the caller never meant
26	      // to ship; the asset tree has no symlinks today, but stage-2 diff/
27	      // backup work will traverse user trees where symlinks are real.
28	      if (stat.isSymbolicLink()) {
29	        options.onSkip?.(entryRelativePath, "symlink");
30	        continue;
31	      }
32	
33	      const destination = join(destinationDir, entry);
34	      if (stat.isDirectory()) {
35	        if (!options.dryRun) mkdirSync(destination, { recursive: true });
36	        copy(source, destination, entryRelativePath);
37	      } else {
38	        if (options.dryRun) {
39	          console.log(`copy ${entryRelativePath}`);
40	        } else {
41	          mkdirSync(dirname(destination), { recursive: true });
42	          copyFileSync(source, destination);
43	        }
44	      }
45	    }
46	  };
47	
48	  copy(src, dest, "");
49	}

