    assert.equal(
      sawFailure,
      false,
      "name-based ExitPromptError must NOT hit the upgrade failed branch",
    );
    process.exitCode = prevExit;
  });

  it("createBackup fails: exit 1, no changes made to target", async () => {
    if (!tarAvailable()) {
      noteTarSkipIfNeeded();
