    const marker = "USER_CONTENT_" + Date.now();
    writeUserFile(target, "docs/README.md", marker);

    const { deps } = makeDeps("all-keep", []);
    const prevExit = process.exitCode;
    process.exitCode = undefined;
    try {
      await upgradeCommand({
